/** Article words: summary + narrative + FAQ. The bibliography is excluded from the band. */
export const UK_ENTRY_WORD_COUNT =
  countWords(UK_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT;

const READING_WORDS_PER_MINUTE = 225;

export const UK_ENTRY_READING_TIME = Math.ceil(
  (countWords(UK_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT) /
    READING_WORDS_PER_MINUTE,
);

